<script setup lang="ts">
import { computed, onMounted, reactive, ref } from "vue";
import { Link, LoaderCircle, Pencil, Plus, Search, Unlink, X } from "lucide-vue-next";
import { useRoute } from "vue-router";
import DataPanel from "@/components/operations/DataPanel.vue";
import ConfirmModal from "@/components/operations/ConfirmModal.vue";
import StatusBadge from "@/components/operations/StatusBadge.vue";
import { platformRepository } from "@/data/repositories/platformRepository";
import { operationsRepository } from "@/data/repositories/operationsRepository";
import type { UiCatalog } from "@/data/models/platform";
import type { UiStudentRecord } from "@/data/models/operations";

const route = useRoute(); const loading = ref(true); const saving = ref(false); const error = ref(""); const showForm = ref(false); const showAttach = ref(false); const search = ref(""); const students = ref<UiStudentRecord[]>([]); const catalog = ref<UiCatalog | null>(null);
const availableEmail = ref(""); const availableStudent = ref<UiStudentRecord | null>(null);
const editingStudent = ref<UiStudentRecord | null>(null); const detachTarget = ref<UiStudentRecord | null>(null); const confirming = ref(false);
const form = reactive({ name: "", email: "", password: "", course_id: "", exam_board_id: "", school_year: "", school_name: "", subject_ids: [] as number[] });
const editForm = reactive({ course_id: null as number | null, exam_board_id: null as number | null, school_year: "", school_name: "", status: "active", preferences: {}, metadata: {}, subject_ids: [] as number[] });
const instituteId = () => Number(route.params.instituteId);
const filtered = computed(() => students.value.filter((item) => `${item.name} ${item.email} ${item.courseName}`.toLowerCase().includes(search.value.toLowerCase())));
async function load() { loading.value = true; try { const [page, catalogData] = await Promise.all([operationsRepository.students({ institute_id: instituteId(), per_page: 100 }), platformRepository.catalog()]); students.value = page.items; catalog.value = catalogData; } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to load students."; } finally { loading.value = false; } }
async function createStudent() { saving.value = true; error.value = ""; try { await operationsRepository.createStudent(instituteId(), { name: form.name, email: form.email, password: form.password, course_id: form.course_id ? Number(form.course_id) : null, exam_board_id: form.exam_board_id ? Number(form.exam_board_id) : null, school_year: form.school_year || null, school_name: form.school_name || null, subject_ids: form.subject_ids }); showForm.value = false; Object.assign(form, { name: "", email: "", password: "", course_id: "", exam_board_id: "", school_year: "", school_name: "", subject_ids: [] }); await load(); } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to create student."; } finally { saving.value = false; } }
function openEdit(student: UiStudentRecord) { editingStudent.value = student; Object.assign(editForm, { course_id: student.courseId, exam_board_id: student.examBoardId, school_year: student.schoolYear, school_name: student.schoolName, status: student.status, preferences: {}, metadata: {}, subject_ids: student.subjectIds }); }
async function saveStudent() { if (!editingStudent.value) return; saving.value = true; try { await operationsRepository.update("students", editingStudent.value.id, editForm); editingStudent.value = null; await load(); } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to update student."; } finally { saving.value = false; } }
async function detach() { if (!detachTarget.value) return; confirming.value = true; try { await operationsRepository.detachStudent(detachTarget.value.id); detachTarget.value = null; await load(); } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to detach student."; } finally { confirming.value = false; } }
async function findAvailable() { saving.value = true; error.value = ""; availableStudent.value = null; try { availableStudent.value = await operationsRepository.findAvailableStudent(instituteId(), availableEmail.value); if (!availableStudent.value) error.value = "No unattached platform student was found for that email."; } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to find student."; } finally { saving.value = false; } }
async function attachAvailable() { if (!availableStudent.value) return; saving.value = true; try { await operationsRepository.attachStudent(instituteId(), availableStudent.value.id); showAttach.value = false; availableStudent.value = null; availableEmail.value = ""; await load(); } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to attach student."; } finally { saving.value = false; } }
onMounted(load);
</script>

<template><div class="space-y-5"><div class="flex flex-wrap items-end justify-between gap-3"><div><p class="text-[12px] font-semibold uppercase tracking-[0.12em] text-violet">Learner administration</p><h2 class="mt-1 text-[26px] font-bold tracking-[-0.035em]">Students</h2><p class="mt-1 text-[13px] text-ink3">Enroll institute students and manage academic profiles.</p></div><div class="flex gap-2"><button class="ops-button-secondary flex items-center gap-2" @click="showAttach = true"><Link :size="15" /> Attach existing</button><button class="ops-button-primary flex items-center gap-2" @click="showForm = true"><Plus :size="15" /> Add student</button></div></div><p v-if="error" class="rounded-xl bg-pink-light px-4 py-3 text-[13px] text-pink">{{ error }}</p><label class="flex max-w-sm items-center gap-2 rounded-xl border border-border bg-bg-card px-3 py-2.5"><Search :size="15" class="text-ink4" /><input v-model="search" class="w-full bg-transparent text-[12px] outline-none" placeholder="Search students" /></label><DataPanel title="Student directory" :description="`${filtered.length} students`" :loading="loading" :empty="!filtered.length"><div class="overflow-x-auto"><table class="w-full min-w-[860px] text-left text-[12px]"><thead class="bg-bg-soft text-ink3"><tr><th class="px-5 py-3">Student</th><th class="px-4 py-3">Course</th><th class="px-4 py-3">School</th><th class="px-4 py-3">Subjects</th><th class="px-5 py-3 text-right">Actions</th></tr></thead><tbody class="divide-y divide-border"><tr v-for="student in filtered" :key="student.id" class="transition hover:bg-bg-soft/70"><td class="px-5 py-3.5"><p class="font-semibold">{{ student.name }}</p><p class="text-ink3">{{ student.email }}</p></td><td class="px-4 py-3.5">{{ student.courseName || 'Not set' }}</td><td class="px-4 py-3.5">{{ student.schoolName || 'Not set' }}<p class="text-[10px] text-ink3">{{ student.schoolYear }}</p></td><td class="max-w-[240px] px-4 py-3.5 text-ink2">{{ student.subjectNames.join(', ') || 'None' }}</td><td class="px-5 py-3.5"><div class="flex justify-end gap-1"><button title="Edit student" class="ops-icon-button" @click="openEdit(student)"><Pencil :size="14" /></button><button title="Detach student" class="ops-icon-button hover:bg-pink-light hover:text-pink" @click="detachTarget = student"><Unlink :size="14" /></button></div></td></tr></tbody></table></div></DataPanel><div v-if="showForm" class="ops-legacy-modal fixed inset-0 z-50 grid place-items-center bg-black/35 p-4" @click.self="showForm = false"><form class="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-bg-card p-5 shadow-xl" @submit.prevent="createStudent"><div class="mb-5 flex justify-between"><div><h3 class="text-[17px] font-bold">Enroll institute student</h3><p class="mt-1 text-[12px] text-ink3">Creates both the user identity and student profile.</p></div><button type="button" @click="showForm = false"><X :size="18" /></button></div><div class="grid gap-3 sm:grid-cols-2"><label class="text-[11px] font-semibold">Name<input v-model="form.name" required class="ops-input" /></label><label class="text-[11px] font-semibold">Email<input v-model="form.email" required type="email" class="ops-input" /></label><label class="text-[11px] font-semibold">Temporary password<input v-model="form.password" required minlength="8" type="password" class="ops-input" /></label><label class="text-[11px] font-semibold">School year<input v-model="form.school_year" class="ops-input" /></label><label class="text-[11px] font-semibold">Exam board<select v-model="form.exam_board_id" class="ops-input"><option value="">None</option><option v-for="item in catalog?.examBoards || []" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label class="text-[11px] font-semibold">Course<select v-model="form.course_id" class="ops-input"><option value="">None</option><option v-for="item in catalog?.courses || []" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label class="text-[11px] font-semibold sm:col-span-2">School name<input v-model="form.school_name" class="ops-input" /></label><fieldset class="sm:col-span-2"><legend class="mb-2 text-[11px] font-semibold">Subjects</legend><div class="grid max-h-40 gap-2 overflow-y-auto rounded-xl border border-border p-3 sm:grid-cols-3"><label v-for="item in catalog?.subjects || []" :key="item.id" class="flex items-center gap-2 text-[11px]"><input v-model="form.subject_ids" type="checkbox" :value="item.id" /> {{ item.name }}</label></div></fieldset></div><div class="mt-5 flex justify-end gap-2"><button type="button" class="ops-button-secondary" @click="showForm = false">Cancel</button><button class="ops-button-primary" :disabled="saving"><LoaderCircle v-if="saving" :size="14" class="animate-spin" />{{ saving ? 'Creating…' : 'Create student' }}</button></div></form></div>
  <div v-if="showAttach" class="ops-legacy-modal fixed inset-0 z-50 grid place-items-center bg-black/35 p-4" @click.self="showAttach = false"><form class="w-full max-w-md rounded-2xl bg-bg-card p-5 shadow-xl" @submit.prevent="availableStudent ? attachAvailable() : findAvailable()"><div class="mb-5 flex justify-between"><div><h3 class="text-[17px] font-bold">Attach platform student</h3><p class="mt-1 text-[12px] text-ink3">Searches by exact email to protect student privacy.</p></div><button type="button" @click="showAttach = false"><X :size="18" /></button></div><label class="text-[11px] font-semibold">Student email<input v-model="availableEmail" required type="email" class="ops-input" @input="availableStudent = null" /></label><div v-if="availableStudent" class="mt-4 rounded-xl border border-border p-4"><p class="text-[13px] font-bold">{{ availableStudent.name }}</p><p class="text-[11px] text-ink3">{{ availableStudent.email }}</p></div><div class="mt-5 flex justify-end gap-2"><button type="button" class="ops-button-secondary" @click="showAttach = false">Cancel</button><button :disabled="saving" class="ops-button-primary"><LoaderCircle v-if="saving" :size="14" class="animate-spin" />{{ saving ? 'Working…' : availableStudent ? 'Attach student' : 'Find student' }}</button></div></form></div>
  <div v-if="editingStudent" class="ops-legacy-modal fixed inset-0 z-50 grid place-items-center bg-black/35 p-4" @click.self="editingStudent = null"><form class="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-2xl border border-border bg-bg-card p-5 shadow-2xl" @submit.prevent="saveStudent"><div class="mb-5 flex justify-between"><div><h3 class="text-[17px] font-bold">Edit student profile</h3><p class="mt-1 text-[12px] text-ink3">{{ editingStudent.name }}</p></div><button type="button" :disabled="saving" @click="editingStudent = null"><X :size="18" /></button></div><div class="grid gap-3 sm:grid-cols-2"><label class="text-[11px] font-semibold">School year<input v-model="editForm.school_year" class="ops-input" /></label><label class="text-[11px] font-semibold">School name<input v-model="editForm.school_name" class="ops-input" /></label><label class="text-[11px] font-semibold">Exam board<select v-model="editForm.exam_board_id" class="ops-input"><option :value="null">None</option><option v-for="item in catalog?.examBoards || []" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label class="text-[11px] font-semibold">Course<select v-model="editForm.course_id" class="ops-input"><option :value="null">None</option><option v-for="item in catalog?.courses || []" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label class="text-[11px] font-semibold sm:col-span-2">Status<select v-model="editForm.status" class="ops-input"><option value="active">Active</option><option value="inactive">Inactive</option><option value="suspended">Suspended</option></select></label><fieldset class="sm:col-span-2"><legend class="mb-2 text-[11px] font-semibold">Subjects</legend><div class="grid max-h-40 gap-2 overflow-y-auto rounded-xl border border-border p-3 sm:grid-cols-3"><label v-for="item in catalog?.subjects || []" :key="item.id" class="flex items-center gap-2 text-[11px]"><input v-model="editForm.subject_ids" type="checkbox" :value="item.id" /> {{ item.name }}</label></div></fieldset></div><div class="mt-5 flex justify-end gap-2"><button type="button" :disabled="saving" class="ops-button-secondary" @click="editingStudent = null">Cancel</button><button :disabled="saving" class="ops-button-primary inline-flex min-w-32 items-center justify-center gap-2"><LoaderCircle v-if="saving" :size="14" class="animate-spin" />{{ saving ? 'Saving…' : 'Update student' }}</button></div></form></div>
  <ConfirmModal :open="Boolean(detachTarget)" title="Detach student?" :message="`Move ${detachTarget?.name || 'this student'} back to platform ownership? Their profile data will be preserved.`" confirm-label="Detach student" :busy="confirming" tone="warning" @close="detachTarget = null" @confirm="detach" />
</div></template>
